const D = { scale:1, warp:0, energy:.6, speed:1, density:.5, hue:262, sides:6, valence:4, x:.5, y:.5, glow:.5, style:'circle-limit', seed:0, alpha:100, act:'stream' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const st = P.style;
const u = Math.min(width, height);
const intn = (K.intensity!=null?K.intensity:0.6);
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat; S.lastBeat = K.beat;

const BW = 232, BH = Math.max(112, Math.round(BW*height/width));
if (!S.g || S.bw!==BW || S.bh!==BH){ if(S.g&&S.g.remove) S.g.remove(); S.g=createGraphics(BW,BH); S.g.pixelDensity(1); S.bw=BW; S.bh=BH; }

let p = Math.max(3, Math.min(8, Math.round(P.sides)));
let q = Math.max(3, Math.min(9, Math.round(P.valence)));
while (1/p + 1/q >= 0.5) q++;
const gkey = p+'|'+q;
if (S.gkey !== gkey){
  S.gkey = gkey;
  const rv = Math.sqrt(Math.cos(Math.PI*(1/p+1/q)) / Math.cos(Math.PI*(1/p-1/q)));
  const cpn = Math.cos(Math.PI/p);
  const dc = (rv*rv+1)/(2*rv*cpn);
  S.rv = rv; S.rc2 = dc*dc-1;
  const cx=[], cy=[];
  for(let k=0;k<p;k++){ const a=k*2*Math.PI/p; cx.push(dc*Math.cos(a)); cy.push(dc*Math.sin(a)); }
  S.cx=cx; S.cy=cy; S.p=p;
}
if (S.seedUsed !== P.seed){ S.seedUsed=P.seed; S.hp = fr(3); S.seedPhase = fr(7); }
const PN = S.p, RC2 = S.rc2, CX = S.cx, CY = S.cy, RV = S.rv;
const RCr = Math.sqrt(RC2), twoRC = 2*RCr;
const hp = (P.hue/360 + S.hp*0.12) % 1;
const seedPhase = S.seedPhase;

const spd = P.speed;
const theta = K.t*(0.028 + spd*0.05);
const cT = Math.cos(theta), sT = Math.sin(theta);
let driftMag = 0.15*(0.5+0.5*Math.sin(K.t*(0.05+spd*0.04)));
if (P.act==='spin') driftMag *= 0.22;
if (P.act==='dive') driftMag = 0.11 + 0.13*(0.5+0.5*Math.sin(K.t*(0.045+spd*0.03)));
const driftDir = K.t*(0.023+spd*0.02);
const amag = Math.min(0.8, P.warp*0.62 + driftMag);
const ax = amag*Math.cos(driftDir), ay = amag*Math.sin(driftDir);

const secDrift = (K.section||0)*0.05;
const exposure = 0.72 + P.energy*0.7 + intn*0.28 + A.rms*0.5;
const leadW = 0.06 - P.density*0.032;
const MAXI = 20 + Math.round(P.density*14);
const Rb = 0.47 * Math.min(BW,BH) * P.scale;
const CXb = BW*0.5 + (P.x-0.5)*BW*0.5;
const CYb = BH*0.5 + (P.y-0.5)*BH*0.5;
const invRb = 1/Rb;
const spark = A.treble*0.6;

// iq cosine jewel palette -> rgb 0..1
function pal(m){
  const r = 0.48 + 0.52*Math.cos(6.2831853*(m + hp + 0.00));
  const g = 0.40 + 0.50*Math.cos(6.2831853*(m + hp + 0.30));
  const b = 0.50 + 0.50*Math.cos(6.2831853*(m + hp + 0.62));
  return [r,g,b];
}

const g = S.g; g.loadPixels(); const px = g.pixels;

for (let j=0;j<BH;j++){
  for (let i=0;i<BW;i++){
    const o = 4*(j*BW+i);
    const zx0 = (i-CXb)*invRb, zy0 = (j-CYb)*invRb;
    const rr = zx0*zx0+zy0*zy0;
    if (rr >= 1.0){
      const dr = Math.sqrt(rr)-1;
      const vig = Math.max(0, 1 - dr*1.3);
      let sr,sg,sb;
      if (st==='woodcut'){ const gn=(fr(i*2.1+j*3.7)-0.5)*0.05; sr=0.90+gn; sg=0.86+gn; sb=0.77+gn; }
      else if (st==='op-art'){ sr=0.09; sg=0.10; sb=0.15; }
      else if (st==='neon-lattice'){ sr=0.015+0.02*vig; sg=0.02+0.03*vig; sb=0.04+0.05*vig; }
      else { sr=0.045*vig+0.012; sg=0.035*vig+0.010; sb=0.10*vig+0.022; }
      // faint limit-circle rim glow
      if (dr < 0.06 && st!=='woodcut' && st!=='op-art'){ const rim=(1-dr/0.06); const c=pal(0.3+secDrift); sr+=c[0]*rim*0.25; sg+=c[1]*rim*0.25; sb+=c[2]*rim*0.3; }
      px[o]=Math.min(255,sr*255); px[o+1]=Math.min(255,sg*255); px[o+2]=Math.min(255,sb*255); px[o+3]=255;
      continue;
    }
    // spin (rotate by -theta)
    const zx1 = zx0*cT + zy0*sT, zy1 = -zx0*sT + zy0*cT;
    // inverse Mobius translate by a
    const numRe = zx1-ax, numIm = zy1-ay;
    const denRe = 1 - ax*zx1 - ay*zy1, denIm = ay*zx1 - ax*zy1;
    const dd = denRe*denRe + denIm*denIm + 1e-9;
    let wx = (numRe*denRe + numIm*denIm)/dd;
    let wy = (numIm*denRe - numRe*denIm)/dd;
    // fold into central cell
    let ring=0, flip=0, code=0, over=false;
    for (let it=0; it<MAXI; it++){
      let best=-1, bestd=RC2;
      for (let k=0;k<PN;k++){ const dx=wx-CX[k], dy=wy-CY[k], d2=dx*dx+dy*dy; if(d2<bestd){bestd=d2;best=k;} }
      if (best<0) break;
      const dx=wx-CX[best], dy=wy-CY[best], d2=dx*dx+dy*dy, f=RC2/d2;
      wx=CX[best]+dx*f; wy=CY[best]+dy*f; ring++; flip^=1; code=(code*31+best)&2047;
      if (it===MAXI-1) over=true;
    }
    // edge distance (approx signed dist to nearest edge circle)
    let ed=1e9;
    for (let k=0;k<PN;k++){ const dx=wx-CX[k], dy=wy-CY[k], d2=dx*dx+dy*dy; const e=Math.abs(d2-RC2)/twoRC; if(e<ed) ed=e; }
    const foldR = Math.sqrt(wx*wx+wy*wy);
    const rimFade = Math.max(0, Math.min(1, (1-rr)*6)); // dark near |z|=1
    const overDim = over ? 0.12 : 1.0;
    const tileM = (0.55 + ring*0.132 + (code/2048)*0.42 + seedPhase + secDrift);
    const dome = 0.72 + 0.42*Math.max(0, 1 - foldR/RV);
    const lead = Math.max(0, Math.min(1, ed/leadW));
    const leadSoft = lead*lead*(3-2*lead);

    let r,gg,b;
    if (st==='circle-limit'){
      const c = pal(tileM);
      const tone = flip ? 1.0 : 0.74;
      const v = tone*dome*exposure*(0.35+0.65*leadSoft)*rimFade*overDim;
      r=c[0]*v; gg=c[1]*v; b=c[2]*v;
    } else if (st==='stained-glass'){
      const c = pal(tileM);
      const sat = 1.15;
      const backlight = 0.55 + 0.65*Math.max(0,1-foldR/RV);
      const leadHard = Math.max(0, Math.min(1, ed/(leadW*1.7)));
      const lh = leadHard*leadHard;
      const v = backlight*exposure*rimFade*overDim;
      r=Math.min(1.2,c[0]*sat)*v*lh; gg=Math.min(1.2,c[1]*sat)*v*lh; b=Math.min(1.2,c[2]*sat)*v*lh;
    } else if (st==='woodcut'){
      const inkTile = ((ring ^ flip ^ (code&1)) & 1)===1;
      const hatch = 0.5+0.5*Math.sin((wx*40+wy*22)+ring*1.7);
      let tone;
      if (ed < leadW*1.2) tone = 0.05; // carved boundary (ink)
      else if (inkTile) tone = 0.10 + hatch*0.16;
      else tone = 0.86 + (fr(i*1.7+j*2.3)-0.5)*0.05;
      tone *= rimFade*0.6+0.4;
      r=tone*1.0; gg=tone*0.96; b=tone*0.86;
    } else if (st==='neon-lattice'){
      const edgeGlow = Math.max(0, 1 - ed/(leadW*2.4));
      const eg = edgeGlow*edgeGlow;
      const c = pal(0.15 + ring*0.19 + secDrift);
      const bright = (1.15+spark)*exposure;
      const inFill = 0.06 + 0.05*Math.max(0,1-foldR/RV); // dim jewel fill so tiles read (not pure black)
      const fc = pal(tileM);
      const baseR=0.03+fc[0]*inFill, baseG=0.04+fc[1]*inFill, baseB=0.07+fc[2]*inFill;
      r=baseR + c[0]*eg*bright*rimFade;
      gg=baseG + c[1]*eg*bright*rimFade;
      b=baseB + c[2]*eg*bright*rimFade;
    } else { // op-art
      const par = ((ring ^ flip) & 1)===1;
      const edgeInk = ed < leadW*0.7;
      const breathe = 0.8 + 0.2*Math.sin(foldR*9.0 + ring*1.3 + K.t*0.6); // optical shimmer -> continuous motion
      if (edgeInk){ r=0.03; gg=0.03; b=0.05; }
      else if (par){ r=0.91; gg=0.88; b=0.77; }
      else { r=0.06; gg=0.07; b=0.17; }
      const f2 = (rimFade*0.5+0.5)*breathe;
      r*=f2; gg*=f2; b*=f2;
    }
    // central backlight bloom (adds warm glow near disk center, energy+audio)
    if (st!=='op-art' && st!=='woodcut'){
      const cg = Math.max(0, 1-rr*2.2)*(0.10+P.energy*0.16+A.bass*0.3+K.pulse*0.12)*P.glow;
      const gc = pal(0.08+secDrift);
      r+=gc[0]*cg; gg+=gc[1]*cg; b+=gc[2]*cg;
    }
    px[o]=Math.max(0,Math.min(255,r*255));
    px[o+1]=Math.max(0,Math.min(255,gg*255));
    px[o+2]=Math.max(0,Math.min(255,b*255));
    px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();
// audio treble sparkle on the disk (partial, additive, never full-frame; skipped when silent)
if ((A.treble>0.02||A.rms>0.02) && st!=='woodcut' && st!=='op-art'){
  push(); blendMode(ADD); noStroke();
  const gl=(A.treble*0.5+A.rms*0.4)*P.glow;
  fill((P.hue+40)%360, 40, 100, Math.min(24, gl*18));
  const dR=2*Math.min(width,height)*0.47*P.scale;
  circle(CXb/BW*width, CYb/BH*height, dR*0.9);
  blendMode(BLEND); pop();
}
